    while changed and rounds < 4:
        changed = False
        rounds += 1

        routes.sort(key=lambda r: (len(r), route_cost(r), r))

        i = 0
        while i < len(routes):
            r = routes[i]
            if not r:
                routes.pop(i)
                changed = True
                continue

            moved = False
            for idx in range(len(r)):
                cust = r[idx]
                d = demand_of(cust)
                best = None

                for t in range(len(routes)):
                    if t == i:
                        continue
                    rt = routes[t]
                    if route_load(rt) + d > capacity:
                        continue
                    base = route_cost(rt)
                    for pos in range(len(rt) + 1):
                        trial = rt[:pos] + [cust] + rt[pos:]
                        delta = route_cost(trial) - base
                        key = (delta, len(trial), t, pos)
                        if best is None or key < best[0]:
                            best = (key, t, pos)

                if best is not None:
                    _, t, pos = best
                    routes[t].insert(pos, cust)
                    del r[idx]
                    changed = True
                    moved = True
                    break

            if not r:
                routes.pop(i)
                changed = True
            else:
                if not moved:
                    i += 1

        for r in routes:
            n = len(r)
            if n < 4:
                continue
            improved = True
            guard = 0
            while improved and guard < 12:
                improved = False
                guard += 1
                base = route_cost(r)
                best_gain = 0
                best_i = None
                best_j = None
                for i in range(n - 2):
                    for j in range(i + 2, n):
                        if i == 0 and j == n - 1:
                            continue
                        rr = r[:i + 1] + r[i + 1:j + 1][::-1] + r[j + 1:]
                        gain = base - route_cost(rr)
                        if gain > best_gain:
                            best_gain = gain
                            best_i = i
                            best_j = j
                if best_i is not None:
                    r[:] = r[:best_i + 1] + r[best_i + 1:best_j + 1][::-1] + r[best_j + 1:]
                    improved = True
                    changed = True

    seen = set()
    cleaned = []
    for r in routes:
        nr = []
        for c in r:
            if c == depot:
                continue
            if c not in seen:
                seen.add(c)
                nr.append(c)
        if nr:
            cleaned.append(nr)

    for c in customer_ids:
        if c not in seen:
            placed = False
            for r in cleaned:
                if route_load(r) + demand_of(c) <= capacity:
                    r.append(c)
                    placed = True
                    break
            if not placed:
                cleaned.append([c])

    cleaned.sort(key=lambda r: (route_cost(r), len(r), r))
    return cleaned
